        ICoinToken(TARGET).mint(attacker, mintAmount);

        vm.stopPrank();

        // Verify balance increased
        uint256 finalBalance = ICoinToken(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase after minting");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

