pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
}

interface IOwnable {
    function owner() external view returns (address);
    function mint(address account, uint256 amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF44DE2b8731cD69d4A727Da0214874aE35559426;
    address attacker = address(this);
    address private ownerAddress;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // First, we need to get the current owner of the contract
        // We'll create an interface to access the owner() function

        // Store the owner address for later use
        ownerAddress = IOwnable(TARGET).owner();
        vm.label(ownerAddress, "Contract Owner");

        // Also label the target contract for clarity
        vm.label(TARGET, "Target Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance of attacker
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);

        // Impersonate the owner to call mint()
        vm.prank(ownerAddress);

        // Call mint() with a large amount (1,000,000 tokens with 18 decimals)
        // We need to use the correct decimals - from the constructor, decimals is a parameter
        // We'll mint 1,000,000 * 10^18 tokens
        uint256 mintAmount = 1_000_000 * 10**18;
        IOwnable(TARGET).mint(attacker, mintAmount);

        // Record final balance
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);

        // Verify the balance increased
        assertGt(finalBalance, initialBalance, "Attacker balance should increase after mint");

        // Also verify the increase is exactly the minted amount (or at least significant)
        assertEq(finalBalance, initialBalance + mintAmount, "Balance should increase by minted amount");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

